</style></head><body><?php include '../../includes/menu_secretaria.php';?><main><section class="header"><h1>Excluir <?php echo htmlspecialchars($tipos[$tipo]);?></h1></section><section class="box"><?php echo $mensagem;?><p><strong>Nome:</strong> <?php echo htmlspecialchars($registro['nome']);?></p><?php if(isset($registro['perfil'])):?><p><strong>Perfil:</strong> <?php echo htmlspecialchars($registro['perfil']);?></p><?php endif;?><?php if(isset($registro['rm'])):?><p><strong>RM:</strong> <?php echo htmlspecialchars($registro['rm']??'');?></p><p><strong>Turma:</strong> <?php echo htmlspecialchars($registro['turma_nome']??'');?></p><?php endif;?><?php if(isset($registro['email'])):?><p><strong>E-mail:</strong> <?php echo htmlspecialchars($registro['email']??'');?></p><?php endif;?><p style="margin-top:18px;color:#8a3030;">Confirma a exclusão deste registro?</p><form method="POST" class="acoes"><input type="hidden" name="tipo" value="<?php echo htmlspecialchars($tipo);?>"><input type="hidden" name="acao" value="<?php echo htmlspecialchars($acao);?>"><input type="hidden" name="turma" value="<?php echo $turma_origem;?>"><input type="hidden" name="id" value="<?php echo $id;?>"><button class="danger" name="confirmar" value="1" type="submit">Confirmar exclusão</button><a class="cancelar" href="consultas_secretaria.php?tipo=<?php echo urlencode($tipo);?>&acao=<?php echo urlencode($acao);?><?php echo $turma_origem?'&turma='.$turma_origem:'';?>">Cancelar</a></form></section></main></body></html>
